@props(['value'=>0,'max'=>100,'size'=>'md','color'=>'primary','showValueLabel'=>false,'label'=>null])
@php $number=max(0,min(100,$max?($value/$max*100):0)); @endphp
<span data-slot="circular-progress" data-size="{{ $size }}" role="progressbar" aria-valuenow="{{ $value }}" aria-valuemin="0" aria-valuemax="{{ $max }}" {{ $attributes->class("app-circular-progress app-color-$color") }} style="--progress-number:{{ $number }}"><svg viewBox="0 0 36 36" aria-hidden="true"><circle class="app-circular-progress-track" cx="18" cy="18" r="15.9" fill="none" stroke-width="3"></circle><circle class="app-circular-progress-value" cx="18" cy="18" r="15.9" fill="none" stroke-width="3" pathLength="100"></circle></svg>@if($showValueLabel)<span class="app-circular-progress-label">{{ round($number) }}%</span>@endif<span class="app-sr-only">{{ $label }}</span></span>
